from pathlib import Path
import re,json,hashlib,runpy
ROOT=Path(__file__).resolve().parent.parent
runpy.run_path(str(ROOT/'_WORK/BUILD_REGISTERS.py'))
d=json.loads((ROOT/'_WORK/COLLECTOR_DATA.json').read_text(encoding='utf-8'))
FM=d['fact_map'];SM=d['source_map']
def write(p,s): (ROOT/p).write_text(s.rstrip()+'\n',encoding='utf-8')
def append(p,s):
    with (ROOT/p).open('a',encoding='utf-8') as f:f.write('\n'+s.rstrip()+'\n')
def F(old):return FM[old]
def R(old):
    fid=FM.get(old,old);return f'[{fid}](RAW_FACTS.md#{fid.lower()})'
def RF(old):
    fid=FM.get(old,old);return f'[{fid}](#{fid.lower()})'

# Normalize the requested contract into 17 groups: 15 original groups + two explicit W2 additions.
p=ROOT/'RAW_FACTS.md';raw=p.read_text(encoding='utf-8')
a=raw.index('## '+F('W2-CONTRACT-F07')+' ');b=raw.index('<a id=',a)
chunk=raw[a:b];lines=chunk.splitlines();inside=False;num=0;out=[]
for line in lines:
    if line.startswith('| Поле/функция |'):inside=True
    elif inside and line.startswith('| ') and not line.startswith('|---'):
        num+=1;line=line.replace('| ',f'| {num}. ',1)
    elif inside and not line.startswith('|'):
        out += [
        '| 16. C privacy/rendition/export lineage | Media owner/auth/policy; original/derived, masking_version/status, original_ref?, view_original/export/attach, recipient/channel/purpose | Нет права → не показывать/не прикладывать; masked thumbnail не гарантирует masked original; отзыв ссылки не удаляет внешнюю копию |',
        '| 17. C cohort/review/measure scope для сводки | cohort_scope, observed_range, review_snapshot_at, selection_policy, camera×rule×version health intervals, measure_applied_at? | Без scope/selection/health — только локальный список; camera-hours не exposure, reviewed-only не recall, disabled не zero |']
        inside=False
    out.append(line)
assert num==15,num
new='\n'.join(out)
new=new.replace('M = нужен','17 групп полей: 15 исходных строк K008 плюс отдельные две группы уточнений W2 privacy/аналитики. Это нормализация требований, не расширение полученного API.\n\nM = нужен',1)
raw=raw[:a]+new+'\n\n'+raw[b:]
# Cross-package shorthand in the original synthesis is resolved by its stated paragraph context.
def fix_fact(raw,fid,replacements):
    a=raw.index('<a id="'+fid.lower()+'"');b=raw.find('<a id=',a+1)
    if b<0:b=len(raw)
    c=raw[a:b]
    for x,y in replacements:c=c.replace(x,y)
    return raw[:a]+c+raw[b:]
raw=fix_fact(raw,'F133', [('F15 — авторский feedback contract','F126 — авторский feedback contract'),('F130 — ограниченные self-reports','F114 — ограниченные self-reports')])
raw=fix_fact(raw,'F134', [('F11 — авторский data-flow','F122 — авторский data-flow'),('Protex F134–F136','Protex F118–F120')])
raw=fix_fact(raw,'F136', [('(F14/F16)','(F125/F127)')])
write('RAW_FACTS.md',raw)

supp=[]
append('_WORK/ID_MAP.md','## Синтезы сборщика без исходного local F-ID\n\n| Semantic alias | Final | Origin |\n|---|---|---|')
def model(fid,title,alias,bases,body):
    global supp
    supp += [f'<a id="{fid.lower()}"></a>',f'## {fid} — {title}',
    f'**Тип:** INF/HYP. **Происхождение:** `{alias}` — синтез сборщика только из '+', '.join(RF(x) for x in bases)+'.',
    '**Дата/проверка:** 23.10.2026; предложенная реконструкция/процедура, НЕ наблюдение работы ХайТэк и НЕ выполненный тест. Публикация/версия/внешний локатор каждого основания сохранены в S-карточках. Реконструкция объединяет разные контексты только как проектный выбор.',
    '',body,'']
    append('_WORK/ID_MAP.md',f'| `{alias}` | [{fid}](../RAW_FACTS.md#{fid.lower()}) | Синтез сборщика по указанным основаниям |')

